import React from 'react';
import { Link } from 'react-router-dom';

const FavouriteItem = ({ property, onRemove }) => {
  const formatPrice = (price, status) => {
    if (status === 'rent') {
      return `£${price}/month`;
    }
    return `£${price.toLocaleString()}`;
  };

  return (
    <div className="favourite-item">
      <div className="favourite-image">
        <img 
          src={property.image} 
          alt={property.title}
          className="favourite-img"
        />
        <div className="favourite-overlay"></div>
      </div>
      
      <div className="favourite-content">
        <div className="favourite-header">
          <h4 className="favourite-title">{property.title}</h4>
          <button 
            className="remove-btn"
            onClick={() => onRemove(property.id)}
            aria-label="Remove from favourites"
          >
            <span className="remove-icon">✕</span>
          </button>
        </div>
        
        <div className="favourite-details">
          <div className="favourite-price">
            {formatPrice(property.price, property.status)}
          </div>
          <div className="favourite-location">
            <span className="location-dot">•</span>
            {property.location}
          </div>
        </div>
        
        <div className="favourite-features">
          <span className="feature-pill">{property.bedrooms} beds</span>
          <span className="feature-pill">{property.bathrooms} baths</span>
          <span className="feature-pill">{property.sqft} sqft</span>
        </div>
        
        <Link to={`/property/${property.id}`} className="btn btn-favourite-view">
          View Property
        </Link>
      </div>
    </div>
  );
};

const FavouritesSidebar = ({ favourites, properties, onRemoveFavourite, onClearFavourites }) => {
  const favouriteProperties = properties.filter(p => favourites.includes(p.id));

  return (
    <div className="favourites-sidebar">
      <div className="sidebar-header">
        <div className="sidebar-title">
          <span className="sidebar-icon">⭐</span>
          <h3>My Favourites</h3>
          <span className="favourite-count">{favouriteProperties.length}</span>
        </div>
        
        {favouriteProperties.length > 0 && (
          <button 
            className="btn-clear-all"
            onClick={onClearFavourites}
            aria-label="Clear all favourites"
          >
            Clear All
          </button>
        )}
      </div>
      
      <div className="sidebar-content">
        {favouriteProperties.length === 0 ? (
          <div className="empty-favourites">
            <div className="empty-icon">🤍</div>
            <h4>No favourites yet</h4>
            <p>Click the heart icon on properties to add them here</p>
            <div className="empty-tips">
              <div className="tip">
                <span className="tip-icon">💡</span>
                <span>Compare properties side by side</span>
              </div>
              <div className="tip">
                <span className="tip-icon">📞</span>
                <span>Contact agents directly</span>
              </div>
              <div className="tip">
                <span className="tip-icon">🔔</span>
                <span>Get price drop notifications</span>
              </div>
            </div>
          </div>
        ) : (
          <>
            <div className="favourites-list">
              {favouriteProperties.map(property => (
                <FavouriteItem
                  key={property.id}
                  property={property}
                  onRemove={onRemoveFavourite}
                />
              ))}
            </div>
            
            <div className="sidebar-stats">
              <div className="stat-card">
                <div className="stat-value">£{Math.max(...favouriteProperties.map(p => p.price)).toLocaleString()}</div>
                <div className="stat-label">Highest Price</div>
              </div>
              <div className="stat-card">
                <div className="stat-value">{favouriteProperties.length}</div>
                <div className="stat-label">Properties</div>
              </div>
            </div>
            
            <div className="sidebar-actions">
              <button className="btn btn-compare">
                Compare Properties
              </button>
              <button className="btn btn-contact">
                Contact Agents
              </button>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default FavouritesSidebar;
